recipes.code:
{
  "inputs": [
    {
      "id": "crisphive-api-key",
      "type": "promptString",
      "description": "Crisphive Developer API key (chsk_live_... = production data, chsk_test_... = isolated sandbox). Create one in the dashboard under Developers -> API keys.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@crisphive/mcp@2.0.0"
      ],
      "env": {
        "CRISPHIVE_API_KEY": "${input:crisphive-api-key}",
        "CRISPHIVE_BASE_URL": "<crisphive-base-url>"
      }
    }
  }
}
